def find_role(apps, country_code, party_id, party_role):
    CredentialsRole = apps.get_model("ocpi22", "CredentialsRole")
    BusinessDetails = apps.get_model("ocpi22", "BusinessDetails")
    try:
        role = CredentialsRole.objects.get(country_code__iexact=country_code, party_id__iexact=party_id)
    except CredentialsRole.DoesNotExist:
        bd = BusinessDetails.objects.create(name=f'Placeholder-{uuid.uuid4()}', website='N/A', logo='N/A')
        role = CredentialsRole.objects.create(country_code=country_code, party_id=party_id, role=party_role,
                                              business_details=bd)
    return role


